{"path":"/workspace/lib/store.js","content":"import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export const STATUSES = ["reading", "finished"];

export function createEmptyStore() {
  return { books: [] };
}

export function normalizeBook(input, existing) {
  const title = cleanText(input?.title);
  const author = cleanText(input?.author);
  const notes = cleanText(input?.notes);
  const status = input?.status === "finished" ? "finished" : "reading";

  if (!title) {
    const error = new Error("Title is required.");
    error.statusCode = 400;
    throw error;
  }
  if (!author) {
    const error = new Error("Author is required.");
    error.statusCode = 400;
    throw error;
  }

  const now = new Date().toISOString();
  return {
    id: existing?.id ?? randomUUID(),
    title,
    author,
    notes,
    status,
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
    finishedAt: status === "finished" ? existing?.finishedAt ?? now : null,
  };
}

export function addBook(store, input) {
  const book = normalizeBook(input);
  return {
    store: { books: [book, ...store.books] },
    book,
  };
}

export function finishBook(store, id) {
  const index = store.books.findIndex((book) => book.id === id);
  if (index === -1) {
    const error = new Error("Book not found.");
    error.statusCode = 404;
    throw error;
  }

  const current = store.books[index];
  if (current.status === "finished") {
    return { store, book: current };
  }

  const book = normalizeBook(
    { ...current, status: "finished" },
    current,
  );
  const books = store.books.slice();
  books[index] = book;
  return { store: { books }, book };
}

export function getBook(store, id) {
  return store.books.find((book) => book.id === id) ?? null;
}

export function listBooks(store) {
  const reading = store.books.filter((book) => book.status === "reading");
  const finished = store.books.filter((book) => book.status === "finished");
  return { reading, finished };
}

export function createStore(filePath) {
  const resolved = path.resolve(filePath);

  async function read() {
    try {
      const raw = await readFile(resolved, "utf8");
      const parsed = JSON.parse(raw);
      if (!parsed || !Array.isArray(parsed.books)) return createEmptyStore();
      return { books: parsed.books.filter(isBook) };
    } catch (error) {
      if (error && error.code === "ENOENT") return createEmptyStore();
      throw error;
    }
  }

  async function write(store) {
    await mkdir(path.dirname(resolved), { recursive: true });
    const tempPath = `${resolved}.${process.pid}.tmp`;
    await writeFile(tempPath, `${JSON.stringify(store, null, 2)}\n`, "utf8");
    await rename(tempPath, resolved);
  }

  return {
    filePath: resolved,
    read,
    write,
    async add(input) {
      const current = await read();
      const next = addBook(current, input);
      await write(next.store);
      return next.book;
    },
    async finish(id) {
      const current = await read();
      const next = finishBook(current, id);
      await write(next.store);
      return next.book;
    },
    async get(id) {
      return getBook(await read(), id);
    },
    async list() {
      return listBooks(await read());
    },
  };
}

function cleanText(value) {
  return String(value ?? "").replace(/\r\n/g, "\n").trim();
}

function isBook(value) {
  return (
    value &&
    typeof value.id === "string" &&
    typeof value.title === "string" &&
    typeof value.author === "string" &&
    (value.status === "reading" || value.status === "finished")
  );
}
