  if (books.length === 0) {
    return `<p class="empty">Nothing here yet.</p>`;
  }

  const items = books
    .map((book) => {
      const finish = canFinish
        ? `<form class="inline" method="post" action="/books/${escapeHtml(book.id)}/finish">
            <button class="secondary" type="submit">Mark finished</button>
          </form>`
        : "";
      return `<li class="book">
        <div>
          <a class="title" href="/books/${escapeHtml(book.id)}">${escapeHtml(book.title)}</a>
          <div class="author">${escapeHtml(book.author)}</div>
        </div>
        <div class="actions">${finish}</div>
      </li>`;
    })
    .join("");

  return `<ul>${items}</ul>`;
