{"path":"/workspace/server.js","content":"import { createServer } from "node:http";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { bookPage, homePage, notFoundPage } from "./lib/html.js";
import { createStore } from "./lib/store.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.env.PORT) || 3000;
const DATA_FILE = process.env.BOOKS_FILE || path.join(__dirname, "data", "books.json");

export function createApp(store) {
  return async function app(req, res) {
    try {
      const url = new URL(req.url || "/", "http://localhost");
      const pathname = url.pathname;

      if (req.method === "GET" && pathname === "/") {
        const lists = await store.list();
        return sendHtml(res, 200, homePage(lists));
      }

      if (req.method === "POST" && pathname === "/books") {
        const fields = await readForm(req);
        try {
          const book = await store.add(fields);
          return redirect(res, `/books/${book.id}`);
        } catch (error) {
          if (error.statusCode !== 400) throw error;
          const lists = await store.list();
          return sendHtml(
            res,
            400,
            homePage({ ...lists, error: error.message, values: fields }),
          );
        }
      }

      const finishMatch = pathname.match(/^\/books\/([^/]+)\/finish$/);
      if (req.method === "POST" && finishMatch) {
        const id = decodeURIComponent(finishMatch[1]);
        try {
          await store.finish(id);
          return redirect(res, `/books/${id}`);
        } catch (error) {
          if (error.statusCode !== 404) throw error;
          return sendHtml(res, 404, notFoundPage());
        }
      }

      const bookMatch = pathname.match(/^\/books\/([^/]+)$/);
      if (req.method === "GET" && bookMatch) {
        const book = await store.get(decodeURIComponent(bookMatch[1]));
        if (!book) return sendHtml(res, 404, notFoundPage());
        return sendHtml(res, 200, bookPage(book));
      }

      return sendHtml(res, 404, notFoundPage());
    } catch (error) {
      console.error(error);
      res.writeHead(500, { "content-type": "text/plain; charset=utf-8" });
      res.end("Something went wrong.");
    }
  };
}

function sendHtml(res, status, html) {
  res.writeHead(status, { "content-type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (chunk) => chunks.push(chunk));
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8");
      const params = new URLSearchParams(raw);
      resolve({
        title: params.get("title") ?? "",
        author: params.get("author") ?? "",
        notes: params.get("notes") ?? "",
      });
    });
    req.on("error", reject);
  });
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];

if (isMain) {
  const store = createStore(DATA_FILE);
  const server = createServer(createApp(store));
  server.listen(PORT, () => {
    console.log(`Book tracker listening on http://localhost:${PORT}`);
  });
}
"}

{"path":"/workspace/lib/store.test.js","content":"import { mkdtemp, readFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { describe, expect, it } from "vitest";
import {
  addBook,
  createEmptyStore,
  createStore,
  finishBook,
  getBook,
  listBooks,
} from "./store.js";

describe("book store", () => {
  it("adds a book as currently reading", () => {
    const result = addBook(createEmptyStore(), {
      title: "  The Left Hand of Darkness  ",
      author: "Ursula K. Le Guin",
      notes: "Cold and brilliant.",
    });

    expect(result.book.title).toBe("The Left Hand of Darkness");
    expect(result.book.status).toBe("reading");
    expect(result.book.finishedAt).toBeNull();
    expect(listBooks(result.store).reading).toHaveLength(1);
    expect(listBooks(result.store).finished).toHaveLength(0);
  });

  it("requires a title and author", () => {
    expect(() => addBook(createEmptyStore(), { title: " ", author: "Someone" })).toThrow(
      /Title is required/,
    );
    expect(() => addBook(createEmptyStore(), { title: "A book", author: " " })).toThrow(
      /Author is required/,
    );
  });

  it("marks a book finished and keeps it findable", () => {
    const added = addBook(createEmptyStore(), {
      title: "Piranesi",
      author: "Susanna Clarke",
    });
    const finished = finishBook(added.store, added.book.id);

    expect(finished.book.status).toBe("finished");
    expect(finished.book.finishedAt).toEqual(expect.any(String));
    expect(getBook(finished.store, added.book.id)?.title).toBe("Piranesi");
    expect(listBooks(finished.store).finished).toHaveLength(1);
    expect(listBooks(finished.store).reading).toHaveLength(0);
  });

  it("persists books to a JSON file", async () => {
    const dir = await mkdtemp(path.join(os.tmpdir(), "books-"));
    const filePath = path.join(dir, "books.json");
    const store = createStore(filePath);

    const book = await store.add({
      title: "Kindred",
      author: "Octavia Butler",
      notes: "Reread the ending.",
    });
    await store.finish(book.id);

    const reopened = createStore(filePath);
    const saved = await reopened.get(book.id);
    const raw = JSON.parse(await readFile(filePath, "utf8"));

    expect(saved).toMatchObject({
      title: "Kindred",
      author: "Octavia Butler",
      notes: "Reread the ending.",
      status: "finished",
    });
    expect(raw.books).toHaveLength(1);
    expect((await reopened.list()).finished.map((item) => item.id)).toEqual([book.id]);
  });
});
"}

