      ${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}
      <form method="post" action="/books">
        <h2 style="margin-top:0">Add a book</h2>
        <label for="title">Title</label>
        <input id="title" name="title" required value="${escapeHtml(formValues.title)}">
        <label for="author">Author</label>
        <input id="author" name="author" required value="${escapeHtml(formValues.author)}">
        <label for="notes">Notes</label>
        <textarea id="notes" name="notes">${escapeHtml(formValues.notes)}</textarea>
        <p style="margin-top:14px"><button type="submit">Add book</button></p>
      </form>
      <h2>Currently reading</h2>
      ${bookList(reading, { canFinish: true })}
      <h2>Finished</h2>
      ${bookList(finished, { canFinish: false })}
    `,
  });
}

export function bookPage(book) {
  const notes = book.notes?.trim()
    ? `<p class="notes">${escapeHtml(book.notes)}</p>`
    : `<p class="empty">No notes yet.</p>`;

  return page({
    title: book.title,
    body: `
      <p><a href="/">All books</a></p>
      <h1>${escapeHtml(book.title)}</h1>
      <p class="author">${escapeHtml(book.author)}</p>
      <p class="meta">${book.status === "finished" ? "Finished" : "Currently reading"}</p>
      ${notes}
      <p class="meta">Share this page: <a href="/books/${escapeHtml(book.id)}">/books/${escapeHtml(book.id)}</a></p>
    `,
  });
}

export function notFoundPage() {
  return page({
    title: "Not found",
    body: `
      <h1>Book not found</h1>
      <p><a href="/">Back to your books</a></p>
    `,
  });
}

function bookList(books, { canFinish }) {
  if (books.length === 0) {
    return `<p class="empty">Nothing here yet.</p>`;
  }

  const items = books
    .map((book) => {
      const finish = canFinish
        ? `<form class="inline" method="post" action="/books/${escapeHtml(book.id)}/finish">
            <button class="secondary" type="submit">Mark finished</button>
          </form>`
        : "";
      return `<li class="book">
        <div>
          <a class="title" href="/books/${escapeHtml(book.id)}">${escapeHtml(book.title)}</a>
          <div class="author">${escapeHtml(book.author)}</div>
        </div>
        <div class="actions">${finish}</div>
      </li>`;
    })
    .join("");

  return `<ul>${items}</ul>`;
}

import { createServer } from "node:http";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { bookPage, homePage, notFoundPage } from "./lib/html.js";
import { createStore } from "./lib/store.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.env.PORT) || 3000;
const DATA_FILE = process.env.BOOKS_FILE || path.join(__dirname, "data", "books.json");

export function createApp(store) {
  return async function app(req, res) {
    try {
      const url = new URL(req.url || "/", "http://localhost");
      const pathname = url.pathname;

      if (req.method === "GET" && pathname === "/") {
        const lists = await store.list();
        return sendHtml(res, 200, homePage(lists));
      }

      if (req.method === "POST" && pathname === "/books") {
        const fields = await readForm(req);
        try {
          const book = await store.add(fields);
          return redirect(res, `/books/${book.id}`);
        } catch (error) {
          if (error.statusCode !== 400) throw error;
          const lists = await store.list();
          return sendHtml(
            res,
            400,
            homePage({ ...lists, error: error.message, values: fields }),
          );
        }
      }

      const finishMatch = pathname.match(/^\/books\/([^/]+)\/finish$/);
      if (req.method === "POST" && finishMatch) {
        const id = decodeURIComponent(finishMatch[1]);
        try {
          await store.finish(id);
          return redirect(res, `/books/${id}`);
        } catch (error) {
          if (error.statusCode !== 404) throw error;
          return sendHtml(res, 404, notFoundPage());
        }
      }

      const bookMatch = pathname.match(/^\/books\/([^/]+)$/);
      if (req.method === "GET" && bookMatch) {
        const book = await store.get(decodeURIComponent(bookMatch[1]));
        if (!book) return sendHtml(res, 404, notFoundPage());
        return sendHtml(res, 200, bookPage(book));
      }

      return sendHtml(res, 404, notFoundPage());
    } catch (error) {
      console.error(error);
      res.writeHead(500, { "content-type": "text/plain; charset=utf-8" });
      res.end("Something went wrong.");
    }
  };
}

function sendHtml(res, status, html) {
  res.writeHead(status, { "content-type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on("data", (chunk) => chunks.push(chunk));
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8");
      const params = new URLSearchParams(raw);
      resolve({
        title: params.get("title") ?? "",
        author: params.get("author") ?? "",
        notes: params.get("notes") ?? "",
      });
    });
    req.on("error", reject);
  });
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];

if (isMain) {
  const store = createStore(DATA_FILE);
  const server = createServer(createApp(store));
  server.listen(PORT, () => {
    console.log(`Book tracker listening on http://localhost:${PORT}`);
  });
}

